import { canonicalHost } from "./credentials-BTv2IfUZ.js";
import { CliError } from "./client-sMzq2PWG.js";
import { resolveClient, withErrorHandling } from "./_lifecycle-shared-_9BzQ9Y2.js";
import { readExecutaIdentity } from "./executa-cache-BFoUtb4J.js";
import { loadExecutaManifest } from "./manifest-B_DjigtQ.js";
import { fetchGitHubIdToken, finalizeBinaryUpload, initBinaryUpload, mintUploadSession, mintUploadSessionViaOidc, uploadBinaryPart } from "./binary-upload-DVhQ0uY0.js";
import { isAbsolute, resolve } from "node:path";
import { closeSync, createReadStream, existsSync, openSync, readSync, statSync } from "node:fs";
import { bold, cyan, dim, green, yellow } from "kleur/colors";
import { createHash } from "node:crypto";

//#region src/commands/executa-upload-binaries.ts
const MAX_ARTIFACT_BYTES = 1024 * 1024 * 1024;
const PART_RETRIES = 3;
/** Expand `{version}` / `{platform}` / `{tool_id}` placeholders. */
function expandArtifactPath(template, vars) {
	return template.replaceAll("{version}", vars.version).replaceAll("{platform}", vars.platform).replaceAll("{tool_id}", vars.toolId);
}
async function sha256File(path) {
	const hash = createHash("sha256");
	for await (const chunk of createReadStream(path)) hash.update(chunk);
	return hash.digest("hex");
}
/**
* Resolve `distribution.binary_artifacts` into a validated, hashed upload
* plan. Throws `CliError(4)` on missing files / oversize artifacts.
*/
async function resolveArtifactPlan(manifest, dir, toolId) {
	const artifacts = manifest.distribution?.binaryArtifacts;
	if (!artifacts || Object.keys(artifacts).length === 0) throw new CliError("executa.json declares no `distribution.binary_artifacts` — this command pushes LOCAL build artifacts directly to the platform. Add e.g.\n  \"distribution\": { \"type\": \"binary\", \"binary_artifacts\": {\n    \"darwin-arm64\": { \"path\": \"dist/my-tool-{version}-darwin-arm64.tar.gz\", \"entrypoint\": \"my-tool\" }\n  } }\n(projects using public `binary_urls` are pull-mirrored at `apps cut` instead)", 4);
	const out = [];
	for (const [platform, art] of Object.entries(artifacts)) {
		const expanded = expandArtifactPath(art.path, {
			version: manifest.version,
			platform,
			toolId
		});
		const absPath = isAbsolute(expanded) ? expanded : resolve(dir, expanded);
		if (!existsSync(absPath)) throw new CliError(`binary_artifacts["${platform}"]: ${absPath} does not exist — build the artifact first (path placeholders: {version} {platform} {tool_id})`, 4);
		const st = statSync(absPath);
		if (!st.isFile()) throw new CliError(`binary_artifacts["${platform}"]: ${absPath} is not a file`, 4);
		if (st.size <= 0 || st.size > MAX_ARTIFACT_BYTES) throw new CliError(`binary_artifacts["${platform}"]: ${absPath} is ${st.size} bytes — must be 1..${MAX_ARTIFACT_BYTES} (1 GiB)`, 4);
		const filename = absPath.split(/[\\/]/).pop();
		out.push({
			platform,
			absPath,
			decl: {
				filename,
				sha256: await sha256File(absPath),
				byte_size: st.size,
				format: art.format,
				entrypoint: art.entrypoint
			}
		});
	}
	out.sort((a, b) => a.platform.localeCompare(b.platform));
	return out;
}
/** Read one part (byte range) of a file into a fresh buffer. */
function readFilePart(path, start, length) {
	const buf = Buffer.alloc(length);
	const fd = openSync(path, "r");
	try {
		let off = 0;
		while (off < length) {
			const n = readSync(fd, buf, off, length - off, start + off);
			if (n <= 0) break;
			off += n;
		}
		if (off !== length) throw new CliError(`short read on ${path} (${off}/${length} bytes)`, 4);
		return buf;
	} finally {
		closeSync(fd);
	}
}
/**
* Drive parts for every platform the init plan marked `upload`.
* Sequential parts with per-part retry — resume comes from `uploaded_parts`.
*/
async function uploadPlannedParts(t, toolId, plan, init, log, retryDelayMs = 500) {
	const outcome = {
		uploadId: init.upload_id,
		skipped: [],
		uploaded: [],
		partsSent: 0
	};
	for (const entry of plan) {
		const asset = init.assets[entry.platform];
		if (!asset) throw new CliError(`server plan is missing platform ${entry.platform}`, 6);
		if (asset.status === "exists") {
			outcome.skipped.push(entry.platform);
			log(dim(`⏭ ${entry.platform}: skipped (content already published)`));
			continue;
		}
		const partSize = asset.part_size;
		const partCount = asset.part_count;
		const already = new Set(asset.uploaded_parts ?? []);
		if (already.size > 0) log(dim(`↩ ${entry.platform}: resuming — ${already.size}/${partCount} part(s) already received`));
		for (let index = 0; index < partCount; index++) {
			if (already.has(index)) continue;
			const start = index * partSize;
			const length = Math.min(partSize, entry.decl.byte_size - start);
			const bytes = readFilePart(entry.absPath, start, length);
			let lastError;
			let sent = false;
			for (let attempt = 1; attempt <= PART_RETRIES; attempt++) try {
				await uploadBinaryPart(t, toolId, init.upload_id, entry.platform, index, bytes);
				sent = true;
				break;
			} catch (e) {
				lastError = e;
				const status = e.status;
				if (status && status < 500 && status !== 429) throw e;
				if (attempt < PART_RETRIES && retryDelayMs > 0) await new Promise((r) => setTimeout(r, retryDelayMs * attempt));
			}
			if (!sent) throw lastError;
			outcome.partsSent += 1;
			log(dim(`↑ ${entry.platform}: part ${index + 1}/${partCount} (${length} bytes)`));
		}
		outcome.uploaded.push(entry.platform);
	}
	return outcome;
}
/**
* Reusable direct-upload flow: hash artifacts → mint upload token → init →
* push missing parts → finalize. Shared by the standalone
* `executa upload-binaries` command, `executa publish` (pre-freeze upload)
* and `apps cut` (bundled-executa pre-upload).
*
* Throws `CliError` on any failure; all-`exists` plans finalize instantly
* (content-addressed idempotency), so re-runs are cheap.
*/
async function uploadExecutaBinaries(opts) {
	const log = opts.log ?? (() => {});
	const { host, dir, manifest, toolId } = opts;
	log(dim(`hashing artifacts for ${toolId} (v${manifest.version})…`));
	const plan = await resolveArtifactPlan(manifest, dir, toolId);
	let uploadToken = opts.uploadToken;
	if (!uploadToken) {
		if (!opts.client) throw new CliError("uploadExecutaBinaries needs either a PAT client or a pre-minted uploadToken", 2);
		({upload_token: uploadToken} = await mintUploadSession(opts.client, toolId));
	}
	const transport = {
		host,
		uploadToken,
		fetchImpl: opts.fetchImpl
	};
	const assets = {};
	for (const e of plan) assets[e.platform] = e.decl;
	const init = await initBinaryUpload(transport, toolId, {
		executa_version: manifest.version,
		assets,
		dry_run: opts.dryRun === true
	});
	const planOut = {};
	for (const e of plan) planOut[e.platform] = {
		...e.decl,
		status: init.assets[e.platform]?.status
	};
	if (opts.dryRun) return {
		toolId,
		version: manifest.version,
		uploadId: init.upload_id,
		dryRun: true,
		skipped: plan.filter((e) => init.assets[e.platform]?.status === "exists").map((e) => e.platform),
		uploaded: [],
		plan: planOut,
		assets: {}
	};
	const outcome = await uploadPlannedParts(transport, toolId, plan, init, log);
	const finalized = await finalizeBinaryUpload(transport, toolId, init.upload_id);
	return {
		toolId,
		version: manifest.version,
		uploadId: init.upload_id,
		dryRun: false,
		skipped: outcome.skipped,
		uploaded: outcome.uploaded,
		plan: planOut,
		assets: finalized.assets
	};
}
async function runExecutaUploadBinaries(opts) {
	return withErrorHandling(async () => {
		const dir = resolve(opts.dir ?? process.cwd());
		const manifest = loadExecutaManifest(dir);
		const log = (msg) => {
			if (!opts.json) console.log(msg);
		};
		let client;
		let host;
		let uploadToken;
		if (opts.oidc) {
			const rawHost = opts.host ?? process.env.ANNA_APP_HOST;
			if (!rawHost) throw new CliError("--oidc needs the Nexus host — pass --host or set ANNA_APP_HOST", 2);
			host = canonicalHost(rawHost);
			log(dim(`using GitHub OIDC trusted publishing (host=${host})`));
		} else {
			const resolved = resolveClient({
				account: opts.account,
				host: opts.host,
				fetchImpl: opts.fetchImpl
			});
			client = resolved.client;
			host = resolved.host;
			log(dim(`using PAT from ${resolved.source} (host=${host})`));
		}
		let toolId = opts.toolId;
		if (!toolId) {
			const identity = readExecutaIdentity(dir);
			if (!identity) throw new CliError(`no .anna/executa.json identity cache in ${dir} — run \`anna-app executa publish\` (standalone) or \`anna-app apps push\` (bundled) once to mint the executa, or pass --tool-id`, 4);
			if (identity.host !== canonicalHost(host)) throw new CliError(`identity cache in ${dir} belongs to ${identity.host}, but the current target is ${canonicalHost(host)} — use --account/--host or re-publish against this host`, 4);
			toolId = identity.tool_id;
		}
		if (opts.oidc) {
			const idToken = await fetchGitHubIdToken({ fetchImpl: opts.fetchImpl });
			({upload_token: uploadToken} = await mintUploadSessionViaOidc({
				host,
				toolId,
				oidcToken: idToken,
				fetchImpl: opts.fetchImpl
			}));
			log(dim("✓ upload token minted via OIDC exchange (no PAT involved)"));
		}
		const result = await uploadExecutaBinaries({
			client,
			host,
			dir,
			manifest,
			toolId,
			uploadToken,
			dryRun: opts.dryRun === true,
			fetchImpl: opts.fetchImpl,
			log
		});
		if (opts.dryRun) {
			if (opts.json) {
				console.log(JSON.stringify({
					tool_id: toolId,
					version: manifest.version,
					dry_run: true,
					upload_id: result.uploadId,
					assets: result.plan
				}, null, 2));
				return 0;
			}
			console.log(yellow(`[dry-run] upload plan for ${toolId} v${manifest.version}:`));
			for (const [platform, decl] of Object.entries(result.plan)) {
				const status = decl.status ?? "?";
				console.log(`  ${platform}: ${status === "exists" ? green("exists (skip)") : cyan("upload")} ` + dim(`${decl.byte_size} bytes, sha256=${decl.sha256.slice(0, 12)}…`));
			}
			return 0;
		}
		if (opts.json) {
			console.log(JSON.stringify({
				tool_id: toolId,
				version: manifest.version,
				host,
				upload_id: result.uploadId,
				skipped: result.skipped,
				uploaded: result.uploaded,
				assets: result.assets
			}, null, 2));
			return 0;
		}
		console.log(green(`✓ ${toolId}: binaries published `) + dim(`(${result.uploaded.length} uploaded, ${result.skipped.length} cached)`));
		for (const [platform, a] of Object.entries(result.assets)) {
			console.log(`  ${bold(platform)} ${dim(`sha256=${a.sha256.slice(0, 12)}…`)}`);
			console.log(`    ${cyan(a.url)}`);
		}
		console.log(dim("→ binaries are served from the platform CDN; `apps cut` / release will pin these hashes"));
		return 0;
	});
}

